#!/usr/bin/env bash
# The wizard library reads "$e[" as an array; it is a string.
# shellcheck disable=SC1087
# Later setup steps use the rest of the library (open_url, ask_secret, set_secret, set_var).
# shellcheck disable=SC2329
#
# Sets up Sema's deploys (RUNBOOK.md): moves the prod stack's state and config from the local
# passphrase backend to Pulumi Cloud (stack untz/sema/prod, ESC environment untz/sema/prod) and
# gates the move on a zero-change preview. Answers stay in ~/.config/sema/deploy.env.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

cd "$(git rev-parse --show-toplevel)"
ENV_FILE="${SEMA_DEPLOY_ENV:-${XDG_CONFIG_HOME:-$HOME/.config}/sema/deploy.env}"
mkdir -p "$(dirname "$ENV_FILE")"
chmod 700 "$(dirname "$ENV_FILE")"

# The old stack lives in the local file backend; it is read, and brought up to date, but never
# changed after the migration. Its config file (passphrase salt and secure values) sits outside
# the repo, because infra/Pulumi.prod.yaml now only imports the ESC environment.
LOCAL_BACKEND="file://~"
LOCAL_STATE="$HOME/.pulumi/stacks/sema/prod.json"
ESC_ENV="sema/prod"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# local_pulumi runs pulumi against the old local stack from a scratch project holding
# infra/Pulumi.yaml and the old stack config, for commands that don't run the program.
local_pulumi() {
  PULUMI_BACKEND_URL="$LOCAL_BACKEND" PULUMI_CONFIG_PASSPHRASE="$PULUMI_CONFIG_PASSPHRASE" \
    pulumi --cwd "$WORK/project" "$@"
}
# local_program runs the program in infra/ against the old local stack and its old config.
local_program() {
  (cd infra && PULUMI_BACKEND_URL="$LOCAL_BACKEND" PULUMI_CONFIG_PASSPHRASE="$PULUMI_CONFIG_PASSPHRASE" \
    pulumi "$@" --stack prod --config-file "$LOCAL_STACK_CONFIG")
}
# cloud_resources prints how many resources the Cloud stack holds (0 if it doesn't exist).
cloud_resources() {
  local count
  count="$( (cd infra && pulumi stack export --stack "$PROD_STACK" 2>/dev/null) |
    jq '.deployment.resources // [] | length' 2>/dev/null || true)"
  printf '%s\n' "${count:-0}"
}
# config_keys prints, as a JSON array, the config keys the old stack file sets.
config_keys() {
  grep -oE '^  [A-Za-z0-9_-]+:[A-Za-z0-9_-]+:' "$LOCAL_STACK_CONFIG" | sed -E 's/^  //; s/:$//' |
    jq -R -s 'split("\n") | map(select(length > 0))'
}
# unlock asks for the passphrase and reads the old stack's config, secrets shown, into $WORK.
unlocked=0
unlock() {
  (( unlocked )) && return 0
  LOCAL_STACK_CONFIG="${LOCAL_STACK_CONFIG:-$(_existing LOCAL_STACK_CONFIG || true)}"
  [[ -n "$LOCAL_STACK_CONFIG" ]] || { warn "Set LOCAL_STACK_CONFIG in $ENV_FILE to the old stack file."; exit 1; }
  mkdir -p "$WORK/project"
  cp infra/Pulumi.yaml "$WORK/project/Pulumi.yaml"
  cp "$LOCAL_STACK_CONFIG" "$WORK/project/Pulumi.prod.yaml"
  if [[ -z "${PULUMI_CONFIG_PASSPHRASE:-}" ]]; then
    printf '  %sPassphrase of the local prod stack:%s ' "$BOLD" "$RESET"
    read -rs PULUMI_CONFIG_PASSPHRASE || { printf '\n'; warn "No passphrase given."; exit 1; }
    printf '\n'
  fi
  if ! local_pulumi config --stack prod --json --show-secrets > "$WORK/local-config.json"; then
    warn "Couldn't read the local stack's config: check the passphrase and $LOCAL_STACK_CONFIG."
    exit 1
  fi
  unlocked=1
}

banner "Sema: prod stack to Pulumi Cloud and ESC"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and sign-ins"
say "This moves the prod stack's state and config to Pulumi Cloud, with your own AWS session."
for tool in aws pulumi jq git go bun make zip; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed: install it and re-run"; exit 1; }
done
if ! aws sts get-caller-identity >/dev/null 2>&1; then
  if [[ -n "${SSH_CONNECTION:-}" ]]; then
    # Over SSH the browser can't reach the CLI's localhost callback, so use a device code.
    step "Signing you in to AWS SSO: open the link it prints and enter the code."
    aws sso login --use-device-code
  else
    step "Signing you in to AWS SSO (a browser window opens)."
    aws sso login
  fi
fi
note "AWS: $(aws sts get-caller-identity --query Arn --output text)"
if ! pulumi whoami --verbose 2>/dev/null | grep -q 'Backend URL: https://'; then
  step "Signing you in to Pulumi Cloud (a browser window opens)."
  pulumi login
fi
note "Pulumi: $(pulumi whoami)"
ask PULUMI_ORG "Pulumi organization for the sema/prod stack (e.g. untz):"
write_env PULUMI_ORG "$PULUMI_ORG"
PROD_STACK="$PULUMI_ORG/sema/prod"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  GITHUB_REPOSITORY_NAME="$(gh repo view --json nameWithOwner -q .nameWithOwner)"
else
  ask GITHUB_REPOSITORY_NAME "GitHub repository CI deploys from (owner/name, e.g. nuntz/sema):"
fi
write_env GITHUB_REPOSITORY_NAME "$GITHUB_REPOSITORY_NAME"
MIGRATED=0
(( $(cloud_resources) > 0 )) && MIGRATED=1
if (( MIGRATED )); then
  note "$PROD_STACK already holds the migrated state: the local stack is no longer used."
else
  [[ -f "$LOCAL_STATE" ]] || { warn "No local state at $LOCAL_STATE, so there is nothing to migrate."; exit 1; }
  say "The old stack config (passphrase salt and encrypted values) lives outside the repo."
  default_config="$(dirname "$ENV_FILE")/Pulumi.prod.local.yaml"
  if [[ -z "$(_existing LOCAL_STACK_CONFIG || true)" && -f "$default_config" ]]; then
    LOCAL_STACK_CONFIG="$default_config"
    note "Old stack config: $LOCAL_STACK_CONFIG"
  else
    ask LOCAL_STACK_CONFIG "Path of the old local Pulumi.prod.yaml:"
  fi
  LOCAL_STACK_CONFIG="${LOCAL_STACK_CONFIG/#\~/$HOME}"
  grep -q '^encryptionsalt:' "$LOCAL_STACK_CONFIG" 2>/dev/null ||
    { warn "$LOCAL_STACK_CONFIG has no encryptionsalt, so it isn't the old passphrase stack file."; exit 1; }
  write_env LOCAL_STACK_CONFIG "$LOCAL_STACK_CONFIG"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Local stack: deploy this checkout so the gate can be zero"
if (( MIGRATED )); then
  note "Skipped: the state is already in Pulumi Cloud. Never run 'pulumi up' on the local stack again."
else
  say "The migration is proven lossless by a zero-change preview, so prod must already run this"
  say "checkout. Previewing the local stack first (it builds the Lambdas and the web app)."
  unlock
  if local_program preview --expect-no-changes; then
    printf '  %s✓ prod%s already matches this checkout\n' "$GREEN" "$RESET"
  else
    warn "The local stack would change prod: the preview above lists what."
    if confirm "Deploy this checkout with the local stack now ('pulumi up', last time on it)?"; then
      STATE_BACKUP="$(dirname "$ENV_FILE")/prod.state.before-last-local-up.json"
      [[ -e "$STATE_BACKUP" ]] || (umask 077 && cp -p "$LOCAL_STATE" "$STATE_BACKUP")
      note "The state before this update is kept at $STATE_BACKUP."
      local_program up
      local_program preview --expect-no-changes ||
        { warn "prod still differs from this checkout after the deploy: fix that, then re-run."; exit 1; }
    else
      warn "Without this, the Cloud preview can't come out at zero changes. Re-run when ready."
      exit 1
    fi
  fi
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "ESC: the $PULUMI_ORG/$ESC_ENV environment"
say "Every prod config value, secrets included, moves into one ESC environment the stack imports."
if pulumi env get "$PULUMI_ORG/$ESC_ENV" >/dev/null 2>&1; then
  note "$PULUMI_ORG/$ESC_ENV already exists."
else
  unlock
  keys="$(config_keys)"
  render() {  # render true|false prints the environment definition, secrets masked or not
    jq -r --argjson keys "$keys" --argjson show "$1" --arg repo "$GITHUB_REPOSITORY_NAME" '
      "values:", "  pulumiConfig:",
      (to_entries[] | select(.key as $k | $keys | index($k)) |
        if .value.secret then
          "    \(.key | tojson):", "      fn::secret: \(if $show then .value.value | tojson else "[secret]" end)"
        else "    \(.key | tojson): \(.value.value | tojson)" end),
      "    \("sema:githubRepository" | tojson): \($repo | tojson)"' "$WORK/local-config.json"
  }
  render false | sed 's/^/    /'
  if confirm "Create $PULUMI_ORG/$ESC_ENV with these values?"; then
    (umask 077 && render true > "$WORK/env.yaml")
    pulumi env init "$PULUMI_ORG/$ESC_ENV" --file "$WORK/env.yaml" >/dev/null
    rm -f "$WORK/env.yaml"
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$PULUMI_ORG/$ESC_ENV"
  else
    warn "The stack can't preview without its environment. Re-run when ready."
    exit 1
  fi
fi
current_repo="$(pulumi env get "$PULUMI_ORG/$ESC_ENV" 'pulumiConfig["sema:githubRepository"]' --value string 2>/dev/null || true)"
if [[ "$current_repo" != "$GITHUB_REPOSITORY_NAME" ]]; then
  pulumi env set "$PULUMI_ORG/$ESC_ENV" 'pulumiConfig["sema:githubRepository"]' "$GITHUB_REPOSITORY_NAME"
  printf '  %s✓ set%s sema:githubRepository = %s\n' "$GREEN" "$RESET" "$GITHUB_REPOSITORY_NAME"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Migrate the state to $PROD_STACK"
if (( MIGRATED )); then
  note "Already migrated: $(cloud_resources) resources in $PROD_STACK."
else
  unlock
  say "Exports the local state with its secrets in the clear (to a private scratch file that is"
  say "deleted on exit), imports it into a new Cloud stack, and leaves $LOCAL_STATE untouched."
  if confirm "Migrate the state now?"; then
    (umask 077 && local_pulumi stack export --stack prod --show-secrets --file "$WORK/state.json")
    note "Exported $(jq '.deployment.resources | length' "$WORK/state.json") resources."
    if ! (cd infra && pulumi stack select "$PROD_STACK" >/dev/null 2>&1); then
      (cd infra && pulumi stack init "$PROD_STACK" --secrets-provider default)
    fi
    (cd infra && PULUMI_CONFIG_PASSPHRASE="$PULUMI_CONFIG_PASSPHRASE" \
      pulumi stack import --stack "$PROD_STACK" --file "$WORK/state.json")
    rm -f "$WORK/state.json"
    printf '  %s✓ imported%s %s resources into %s\n' "$GREEN" "$RESET" "$(cloud_resources)" "$PROD_STACK"
  else
    warn "Nothing migrated. Re-run when ready."
    exit 1
  fi
fi
provider="$( (cd infra && pulumi stack export --stack "$PROD_STACK") | jq -r '.deployment.secrets_providers.type // "none"')" ||
  { warn "Couldn't read $PROD_STACK's secrets provider: check 'pulumi stack export --stack $PROD_STACK'."; exit 1; }
if [[ "$provider" != "service" ]]; then
  say "The stack's secrets provider is '$provider': switching it to Pulumi Cloud's."
  [[ "$provider" == "passphrase" ]] && unlock
  (cd infra && PULUMI_CONFIG_PASSPHRASE="${PULUMI_CONFIG_PASSPHRASE:-}" \
    pulumi stack change-secrets-provider default --stack "$PROD_STACK")
fi
printf '  %s✓ secrets%s are encrypted by Pulumi Cloud\n' "$GREEN" "$RESET"
if [[ "$(cat infra/Pulumi.prod.yaml)" != "$(printf 'environment:\n  - %s' "$ESC_ENV")" ]]; then
  warn "Pulumi rewrote infra/Pulumi.prod.yaml; it should hold only the environment import:"
  sed 's/^/    /' infra/Pulumi.prod.yaml
  warn "Check that its values are in ESC, then put back just the import (environment: - $ESC_ENV)."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Gate: the Cloud stack reads the same config and changes nothing"
(cd infra && pulumi stack select "$PROD_STACK")
if (( unlocked )); then
  keys="$(config_keys)"
  (cd infra && pulumi config --stack "$PROD_STACK" --json --show-secrets) > "$WORK/cloud-config.json"
  if jq -e -n --argjson keys "$keys" --slurpfile old "$WORK/local-config.json" --slurpfile new "$WORK/cloud-config.json" '
      [$keys[] as $k | ($old[0][$k].value == $new[0][$k].value)] | all' >/dev/null; then
    printf '  %s✓ config%s: every value of the local stack reads the same from ESC\n' "$GREEN" "$RESET"
  else
    warn "Some config values differ between the local stack and ESC; fix the environment with"
    warn "'pulumi env edit $PULUMI_ORG/$ESC_ENV' and re-run."
    exit 1
  fi
fi
say "Previewing $PROD_STACK (it builds the Lambdas and the web app again)."
if (cd infra && pulumi preview --stack "$PROD_STACK" --expect-no-changes); then
  printf '  %s✓ zero changes%s: the migration is lossless\n' "$GREEN" "$RESET"
else
  warn "The Cloud stack would change prod. Don't deploy or land anything else until this preview"
  warn "is clean: compare its config with the local stack's and fix ESC, then re-run."
  exit 1
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Deploy by hand against the Cloud stack"
say "'make deploy' now runs 'pulumi up' on $PROD_STACK, then invalidates CloudFront."
note "It's optional here: the preview just showed it would change nothing."
if confirm "Run 'make deploy' now?"; then
  make deploy PULUMI_ORG="$PULUMI_ORG"
else
  SKIPPED+=("a deploy by hand: make deploy (RUNBOOK.md → Deploy by hand)")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Retire the passphrase"
say "Pulumi Cloud now encrypts the stack's secrets, so nothing reads the passphrase any more."
step "Remove PULUMI_CONFIG_PASSPHRASE from your shell profile, if you set it there."
step "Keep the passphrase with the backup only while you still want it: the local state and"
step "its config can't be decrypted without it."
note "Backup state: $LOCAL_STATE (left untouched by the migration)"
note "Backup config: ${LOCAL_STACK_CONFIG:-the old local Pulumi.prod.yaml}"
warn "Never 'pulumi up' against the local backend again: it would fork prod's state."
pause

finish
}

run_wizard "$@"; exit
